// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 targetBlock) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        uint256 b = bound(targetBlock, block.number + 1, block.number + 1024);

        vm.warp(block.timestamp + 1);

        vm.deal(caller, 20 ether);

        vm.roll(b);

        uint256 rem = b % 15;

        vm.prank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");
        vm.assume(ok);

        bool observedZero = address(c).balance == 0;
        bool expectedZero = (rem == 0);

        assertTrue(observedZero == expectedZero);
    }
}
